Takieddin/passport-wizard/git/trees/6fd525988635c3c903bb065559f64e34837727b2"},"url":"https://api.github.com/repos/ZaidTakieddin/passport-wizard/git/commits/a247ecd3a4e9ef223a6cd8ebbfdd61992f899e71","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/59053451?v=4","events_url":"https://api.github.com/users/Zaid-Takieddin/events{/privacy}","followers_url":"https://api.github.com/users/Zaid-Takieddin/followers","following_url":"https://api.github.com/users/Zaid-Takieddin/following{/other_user}","gists_url":"https://api.github.com/users/Zaid-Takieddin/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Zaid-Takieddin","id":59053451,"login":"Zaid-Takieddin","node_id":"MDQ6VXNlcjU5MDUzNDUx","organizations_url":"https://api.github.com/users/Zaid-Takieddin/orgs","received_events_url":"https://api.github.com/users/Zaid-Takieddin/received_events","repos_url":"https://api.github.com/users/Zaid-Takieddin/repos","site_admin":false,"starred_url":"https://api.github.com/users/Zaid-Takieddin/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Zaid-Takieddin/subscriptions","type":"User","url":"https://api.github.com/users/Zaid-Takieddin","user_view_type":"public"},"html_url":"https://github.com/ZaidTakieddin/passport-wizard/commit/a247ecd3a4e9ef223a6cd8ebbfdd61992f899e71","node_id":"C_kwDOU5_Ry9oAKGEyNDdlY2QzYTRlOWVmMjIzYTZjZDhlYmJmZGQ2MTk5MmY4OTllNzE","parents":[{"html_url":"https://github.com/ZaidTakieddin/passport-wizard/commit/1b1a05a99e3dc2c6b73933e897976c6805092be7","sha":"1b1a05a99e3dc2c6b73933e897976c6805092be7","url":"https://api.github.com/repos/ZaidTakieddin/passport-wizard/commits/1b1a05a99e3dc2c6b73933e897976c6805092be7"}],"sha":"a247ecd3a4e9ef223a6cd8ebbfdd61992f899e71","url":"https://api.github.com/repos/ZaidTakieddin/passport-wizard/commits/a247ecd3a4e9ef223a6cd8ebbfdd61992f899e71"},{"author":{"avatar_url":"https